from __future__ import annotations
import argparse,subprocess
from pathlib import Path
from zipfile import ZIP_DEFLATED,ZIP_STORED,ZipFile

CONTENT='''<?xml version="1.0" encoding="UTF-8"?><office:document-content xmlns:office="urn:oasis:names:tc:opendocument:xmlns:office:1.0" xmlns:draw="urn:oasis:names:tc:opendocument:xmlns:drawing:1.0" xmlns:text="urn:oasis:names:tc:opendocument:xmlns:text:1.0" office:version="1.2"><office:body><office:drawing><draw:page draw:name="Core Services" draw:style-name="dp1"><draw:frame draw:style-name="gr1" draw:name="shape1" svg:width="12cm" svg:height="2cm" xmlns:svg="urn:oasis:names:tc:opendocument:xmlns:svg-compatible:1.0"><draw:text-box><text:p>[[CORE_LABEL]]</text:p><text:p>[[CORE_LINK]]</text:p><text:p>Rev 2.5</text:p></draw:text-box></draw:frame></draw:page><draw:page draw:name="Customer Platform" draw:style-name="dp1"><draw:frame draw:style-name="gr1" draw:name="shape2" svg:width="12cm" svg:height="2cm" xmlns:svg="urn:oasis:names:tc:opendocument:xmlns:svg-compatible:1.0"><draw:text-box><text:p>[[API_LABEL]]</text:p><text:p>[[API_CAPACITY]]</text:p><text:p>Rev 2.5</text:p></draw:text-box></draw:frame></draw:page><draw:page draw:name="Analytics Platform" draw:style-name="dp1"><draw:frame draw:style-name="gr1" draw:name="shape3" svg:width="12cm" svg:height="2cm" xmlns:svg="urn:oasis:names:tc:opendocument:xmlns:svg-compatible:1.0"><draw:text-box><text:p>[[WAREHOUSE_LABEL]]</text:p><text:p>[[INGEST_CAPACITY]]</text:p><text:p>Rev 2.5</text:p></draw:text-box></draw:frame></draw:page><draw:page draw:name="Resilience Layer" draw:style-name="dp1"><draw:frame draw:style-name="gr1" draw:name="shape4" svg:width="12cm" svg:height="2cm" xmlns:svg="urn:oasis:names:tc:opendocument:xmlns:svg-compatible:1.0"><draw:text-box><text:p>[[CACHE_LABEL]]</text:p><text:p>[[FAILOVER_TARGET]]</text:p><text:p>Rev 2.5</text:p></draw:text-box></draw:frame></draw:page></office:drawing></office:body></office:document-content>'''
def odg(path):
 with ZipFile(path,"w") as z:
  z.writestr("mimetype","application/vnd.oasis.opendocument.graphics",compress_type=ZIP_STORED);z.writestr("content.xml",CONTENT,compress_type=ZIP_DEFLATED);z.writestr("styles.xml",'<office:document-styles xmlns:office="urn:oasis:names:tc:opendocument:xmlns:office:1.0" office:version="1.2"><office:styles/><office:automatic-styles/><office:master-styles/></office:document-styles>');z.writestr("meta.xml",'<office:document-meta xmlns:office="urn:oasis:names:tc:opendocument:xmlns:office:1.0" office:version="1.2"><office:meta/></office:document-meta>');z.writestr("settings.xml",'<office:document-settings xmlns:office="urn:oasis:names:tc:opendocument:xmlns:office:1.0" office:version="1.2"><office:settings/></office:document-settings>');z.writestr("META-INF/manifest.xml",'<manifest:manifest xmlns:manifest="urn:oasis:names:tc:opendocument:xmlns:manifest:1.0" manifest:version="1.2"><manifest:file-entry manifest:full-path="/" manifest:media-type="application/vnd.oasis.opendocument.graphics"/><manifest:file-entry manifest:full-path="content.xml" manifest:media-type="text/xml"/></manifest:manifest>')
def main():
 p=argparse.ArgumentParser();p.add_argument("--workspace",required=True);p.add_argument("--source-dir",required=True);p.add_argument("--open-draw",action="store_true");a=p.parse_args();root=Path(a.workspace).expanduser().resolve()/"architecture";spec=root/"specs";out=root/"out";spec.mkdir(parents=True,exist_ok=True);out.mkdir(exist_ok=True);odg(root/"system_topology.odg")
 (spec/"core_services.txt").write_text("Core Services page: label Identity Gateway; link note mTLS / token exchange; page footer Rev 2.6.\nCustomer Platform page: label Customer API; capacity note 120 requests/minute; page footer Rev 2.6.\n",encoding="utf-8")
 (spec/"platform_layers.txt").write_text("Analytics Platform page: label Analytics Warehouse; capacity note Nightly ingest: 40 GB; page footer Rev 2.6.\nResilience Layer page: label Regional Cache; failover note Failover target: west-2; page footer Rev 2.6.\n",encoding="utf-8")
 if a.open_draw:subprocess.Popen(["libreoffice","--draw",str(root/"system_topology.odg")],start_new_session=True)
if __name__=="__main__":main()
